# -*- coding: utf-8 -*-
import json, re, glob
JQ = '/tmp/claude-0/-home-user-Pruebas/978f574d-1019-54bc-bb45-9f4fddd102bb/scratchpad/jq'
D = {}
for p in glob.glob(JQ + '/J*/passages.json'):
    for r in json.load(open(p, encoding='utf8')): D[r['id']] = r
def _cut(t, a, b):
    if a:
        i = t.index(a); t = t[i:]
    if b:
        j = t.index(b) + len(b); t = t[:j]
    return t
def clean(t):
    t = re.sub(r'\s*\(\d+\)', '', t); t = t.replace('[one OCR line lost]', '…')
    return re.sub(r'\s+', ' ', t).strip()
def G(i, a=None, b=None): return clean(_cut(D[i]['greek'], a, b))
def EN(i, a=None, b=None): return clean(_cut(D[i]['english'], a, b))
OTTO1 = 'Griego: Otto 1842 vol. 1, leído en imagen de página por un investigador'
RAU = 'Griego: Rauschen 1911, escaneo abierto (imágenes revisadas por un investigador)'
TROL = 'Griego: Trollope 1846, leído en imagen de página por un investigador'
MIGNE = 'Griego: OCR de Migne PG 6 (1857), sin cotejar con imagen'
OTTO2 = 'Griego: OCR de Otto 1842-43 (vol. 2), sin cotejar con imagen'
ANF = 'Inglés: Dods y Reith, ANF vol. 1'
def Q(i, lang, txt, es, ref, src): return dict(id=i, lang=lang, txt=txt, es=es, ref=ref, src=src)
S = []
def add(id, title, sub, quotes, res): S.append(dict(id=id, title=title, sub=sub, quotes=quotes, res=res))

add('JM01', 'Quién es Justino y qué obras son suyas', 'Tres obras auténticas; varias atribuidas son posteriores',
 [Q('J11-10','en',EN('J11-10'),'La tercera clase está formada por las que sin duda no son obras de Justino: 1. Exposición de la fe verdadera; 2. Respuestas a los ortodoxos; 3. Cuestiones cristianas a los gentiles; 4. Cuestiones gentiles a los cristianos; 5. Epístola a Zenas y Serenio; y 6. Refutación de ciertas doctrinas de Aristóteles. […] No cabe duda de que las otras se escribieron después del Concilio de Nicea […]','ANF vol. 1, Nota introductoria a Justino Mártir','Inglés: editores de la ANF (s. XIX); no revisé la crítica reciente'),
  Q('J11-12','en',EN('J11-12', None, 'Questions and Answers to the Greeks”'),'Bull cita a Sandio, que decía que Justino enseñó «que hubo un tiempo en que lo engendrado no existía» y que «engendrado» y «hecho» no se diferencian en la realidad. Bull responde que Sandio ha citado a los antiguos sin juicio o contra su conciencia: lo segundo lo tomó de las «Preguntas y respuestas a los griegos», obra que (según Bull) todos reconocen espuria […]','Bull, Defensio fidei Nicaenae, 1851 (Oxford), vol. 2, p. 406','Inglés: Bull (trad. 1851); texto cortado en el original')],
 '<b>Quién.</b> Justino (hacia 100-165), filósofo cristiano, mártir en Roma. De su obra se leen como <b>auténticas</b> la <i>Primera Apología</i>, la <i>Segunda Apología</i> y el <i>Diálogo con Trifón</i>. <b>Aviso metodológico:</b> existen escritos atribuidos a Justino (<i>Exposición de la fe recta</i>, <i>Preguntas y respuestas a los griegos</i>, <i>Sobre la monarquía</i>, etc.) que los editores de la ANF consideran «sin duda» no suyos; <b>no los uso</b>. Cualquier cita de «Justino» que diga «hubo un tiempo en que…» merece sospecha hasta comprobar la obra. <b>Límite:</b> la clasificación es la de los editores del XIX; no cotejé estudios recientes.')

add('JM02', '1 Apología 6: «al Hijo… y al Espíritu profético, los adoramos»', 'El pasaje con problema textual de los «ángeles»',
 [Q('J1-02','gr',G('J1-02'),'[…] y al ejército de los otros ángeles buenos que le siguen y se le asemejan, y al Espíritu profético, adoramos y veneramos, honrándolos con razón y verdad y comunicando sin envidia a todo el que quiera aprender, como hemos sido enseñados.','1 Apol. 6 (Otto 1842, p. 150)',OTTO1+'; el inicio de la frase es 6.1 (ver abajo)'),
  Q('J1-01','gr',G('J1-01','ἀλλ\' ἐκεῖνόν τε'),'Pero a Él, y al Hijo que de Él vino y nos enseñó esto […]','1 Apol. 6.1 (Otto 1842, p. 148)',OTTO1+'; la frase se corta en la fuente')],
 '<b>Qué dice.</b> Padre, Hijo y Espíritu profético son nombrados juntos como objeto de adoración o veneración. <b>Por qué es difícil.</b> La mención de los «ángeles» en medio de la frase es un <b>problema textual y de puntuación</b> conocido: Otto recoge en el aparato (p. 150) lecturas distintas (unir los ángeles a «nos enseñó», conjeturas como «caudillo» por «ejército», o leer que se adora a los ángeles). Los adversarios la usan para decir que Justino «adora ángeles» o que el Espíritu es un ser entre otros. <b>Resolución.</b> (1) La sintaxis no es segura: <b>no se debe fundar nada sólo en este pasaje</b>. (2) En otros lugares Justino nombra al Padre, al Hijo y al Espíritu <i>sin</i> ángeles: la fórmula bautismal (1 Apol. 61), la bendición eucarística (65, 67), el «segundo lugar… tercer orden» (1 Apol. 13), y Platón leído como «segundo» y «tercero» (60). (3) Y en 2 Apol. 13 el Verbo es adorado «después de Dios». <b>Límite.</b> Quien lea aquí un culto a los ángeles tiene un texto difícil de descartar sólo con gramática.')

add('JM03', 'Pasaje difícil A (1 Apol. 13): «lo tenemos en segundo lugar, y al Espíritu profético en tercer orden»', 'Orden, no rango de naturaleza',
 [Q('J1-05','gr',G('J1-05'),EN('J1-05') and 'Nuestro maestro en estas cosas es Jesucristo, que nació para esto y fue crucificado bajo Poncio Pilato, procurador de Judea en tiempos de Tiberio César; y que lo honramos con razón, habiendo aprendido que es Hijo del Dios verdadero mismo y teniéndolo en segundo lugar, y al Espíritu profético en tercer orden, lo demostraremos.','1 Apol. 13.3 (Otto 1842, p. 164; ver captura JM20)',OTTO1+' (la vi yo en la imagen)'),
  Q('J1-06','gr',G('J1-06'),'Pues aquí nos acusan de locura, diciendo que damos el segundo lugar, después del Dios inmutable y siempre existente, engendrador de todos, a un hombre crucificado, ignorando el misterio que hay en esto, al cual os exhortamos a prestar atención mientras os lo explicamos.','1 Apol. 13.4 (Otto 1842, p. 164)',OTTO1)],
 '<b>Objeción.</b> «Segundo lugar» y «tercer orden» = escala jerárquica: el Hijo inferior al Padre, el Espíritu inferior al Hijo. <b>Resolución.</b> (1) El texto habla de <b>honra y adoración</b> (<i>timômen</i>, 13.3) dirigida al Hijo; Justino lo defiende contra quienes llaman «locura» dar a un crucificado el segundo lugar «después del Dios inmutable y eterno» (13.4): la polémica no es que el Hijo sea inferior, sino que sea digno de adoración. (2) «Lugar» (<i>chôra</i>) y «orden» (<i>táxis</i>) expresan <b>orden de origen</b>: el Padre sin principio, el Hijo del Padre, el Espíritu «profético»; la tradición posterior (Tertuliano, <i>Adv. Prax.</i> 8: «el tercero es el Espíritu») lo formulará como orden sin desigualdad de naturaleza (ver pack de Tertuliano). <b>Límite.</b> Justino no dice «consustancial» ni «igual»: es un testigo de <b>distinción y adoración</b>, no de igualdad formulada.')

add('JM04', '1 Apol. 21-23: el Verbo «primer engendrado de Dios», «hijo único en sentido propio»', 'Qué reclama Justino y qué concede a los paganos',
 [Q('J1-11','gr',G('J1-11'),'Y si decimos que fue engendrado de Dios de modo peculiar, distinto de la generación común, como Verbo de Dios, según dijimos antes, sea esto común con vosotros, que decís que Hermes es el verbo mensajero de parte de Dios.','1 Apol. 22 (Otto 1842, p. 184)',OTTO1),
  Q('J1-12','gr',G('J1-12'),'[…] y Jesucristo es el único que en sentido propio ha sido engendrado como Hijo de Dios, siendo su Verbo y primogénito y poder, y que, hecho hombre por su voluntad, nos enseñó esto para la transformación y restauración del género humano.','1 Apol. 23 (Otto 1842, p. 186)',OTTO1),
  Q('J1-10','gr',G('J1-10'),'El que se llama Hijo de Dios, Jesús, aunque fuera sólo hombre por generación común, por su sabiduría sería digno de llamarse Hijo de Dios; pues todos los escritores llaman a Dios padre de hombres y dioses.','1 Apol. 22 (Otto 1842, p. 184)',OTTO1)],
 '<b>Qué dice.</b> «Único» (<i>mónos ídiôs</i>) Hijo engendrado, «Verbo, primogénito y poder»; engendrado «de modo peculiar» (<i>idíôs</i>), no por unión carnal. <b>Objeciones.</b> (a) La comparación con los hijos de Júpiter y con Hermes, «verbo mensajero», parece colocar al Verbo entre los intermediarios. (b) El «aunque fuera sólo hombre» (22) suena a una cristología baja. <b>Resolución.</b> (a) Justino usa la analogía <b>ad hominem</b> («sea esto común con vosotros»): quiere decir que una generación no humana no es absurda para sus lectores; lo que reclama como propio es «único en sentido propio» (23), que los dioses de los mitos no tienen. (b) El «aunque» es una <b>concesión retórica condicional</b> (<i>ei kaì … mónon</i>); su afirmación positiva viene en la frase siguiente (22) y en 23. <b>Límite.</b> Aquí «primogénito» y «poder» son los términos que arrianos y unitarios citan; el texto no dice «eterno».')

add('JM05', '1 Apol. 32-33 y 46: «primer poder después del Padre», «el Espíritu y el poder… no son otra cosa que el Verbo»', 'El pasaje donde el Espíritu parece identificarse con el Verbo',
 [Q('J2-01','gr',G('J2-01','Ἡ δὲ πρώτη'),'Y el primer poder después del Padre de todo y Señor Dios, e Hijo, es el Verbo; de qué modo hecho carne se hizo hombre, lo diremos en lo que sigue.','1 Apol. 32.10 (Rauschen 1911, p. 64)',RAU),
  Q('J2-03','gr',G('J2-03'),'Hay que entender que «el Espíritu y el poder que vienen de Dios» no son otra cosa que el Verbo, que es también primogénito de Dios, como mostró Moisés el profeta ya citado; y éste, al venir sobre la virgen y cubrirla con su sombra, la hizo concebir no por unión sino por poder.','1 Apol. 33.6 (Rauschen 1911, p. 66)',RAU),
  Q('J2-05','gr',G('J2-05'),'Hemos sido enseñados que Cristo es el primogénito de Dios, y antes lo hemos declarado: es el Verbo del cual todo género de hombres participa. Y los que vivieron con razón son cristianos, aunque fueran tenidos por ateos.','1 Apol. 46.2-3 (Rauschen 1911, p. 80)',RAU)],
 '<b>Por qué es difícil.</b> 33.6 identifica, al comentar Lc 1:35, «Espíritu» y «poder» con el <b>Verbo</b>: parece que no hay un Espíritu distinto. «Primer poder» (32.10) suena a atributo, y «participa» (46.2) a algo repartido. <b>Resolución.</b> (1) La frase misma de 32.10 dice «primer poder… <b>e Hijo</b>, es el Verbo»: ese «poder» tiene nombre personal. (2) 33.6 es <b>exégesis de un versículo</b> (Lc 1:35), no una teoría de la Trinidad: el mismo Justino nombra al Espíritu aparte en 1 Apol. 6, 13, 60, 61, 65, 67 y en el <i>Diálogo</i> («el Espíritu profético» habla, 36, 37, 54). (3) La confusión Espíritu/Verbo/Sabiduría es un rasgo del siglo II que Ireneo y los siglos IV-V precisarán (ver el pack de Teófilo, UG15). (4) «Participar del Verbo» (46) es participar en el <b>Logos universal</b> por la razón, no repartir la persona del Verbo. <b>Límite.</b> La pneumatología de Justino es poco desarrollada; es la parte más débil de su caso trinitario.')

add('JM06', '1 Apol. 60-63: Platón «segundo» y «tercero»; el Verbo «es también Dios»; «el Hijo no es el Padre»', 'Distinción del Padre y del Hijo frente a quienes los identifican',
 [Q('J2-08','gr',G('J2-08','Καὶ τὸ εἰπεῖν'),'[…] Y que dijera «tercero» es porque leyó en Moisés que el Espíritu de Dios se movía sobre las aguas: pues da el segundo lugar al Verbo que viene de Dios, que dijo que estaba puesto en cruz en el universo, y el tercero al Espíritu que se decía que se movía sobre el agua.','1 Apol. 60.6-7 (Rauschen 1911, p. 96)',RAU),
  Q('J2-14','gr',G('J2-14'),'Los judíos, creyendo siempre que el Padre del universo había hablado a Moisés, siendo el que le habló el Hijo de Dios, que ha sido llamado ángel y apóstol, son justamente refutados, tanto por el Espíritu profético como por el mismo Cristo, de no conocer ni al Padre ni al Hijo. Pues los que dicen que el Hijo es el Padre son refutados, ya que ni conocen al Padre ni saben que hay un Hijo del Padre del universo; el cual, siendo Verbo y primogénito de Dios, es también Dios.','1 Apol. 63.14-15 (Rauschen 1911, p. 104)',RAU),
  Q('J2-09','gr',G('J2-09'),'Luego son llevados por nosotros donde hay agua, y son regenerados al modo de regeneración como también nosotros fuimos regenerados; pues en el nombre del Padre de todo y Señor Dios, y de nuestro Salvador Jesucristo, y del Espíritu Santo, hacen entonces el baño en el agua.','1 Apol. 61.3 (Rauschen 1911, p. 98)',RAU)],
 '<b>Qué dice.</b> «El Hijo… <b>es también Dios</b>» (63.15: <i>kaì theòs hypárchei</i>); «los que dicen que el Hijo es el Padre» no conocen a ninguno (anti-modalismo); la fórmula bautismal es trinitaria. <b>Objeciones.</b> (a) El Hijo es «ángel y apóstol» (63.5, 14): ¿un enviado creado? (b) La aplicación a Platón de «segundo» y «tercero» (60) parece una analogía filosófica. <b>Resolución.</b> (a) «Ángel» y «apóstol» son <b>funciones de mensajero</b> (63.5: «anuncia lo que hay que conocer»): la misma frase dice que quien habló a Moisés «era el Hijo de Dios»; Justino no identifica al Hijo con un ángel creado. (b) Justino cree que Platón tomó de Moisés; lo que importa es que su lectura cristiana distingue Padre, Verbo y Espíritu y dice «Dios» del Verbo. <b>Límite.</b> «Dios» (63.15) viene calificado: «Verbo y primogénito de Dios… es también Dios»: no es «Dios de la misma sustancia».')

add('JM07', '2 Apol. 6 y 13: «el Verbo… estaba con él y era engendrado antes de las obras»; «después de Dios adoramos al Verbo»', 'La frase de Newman «necesita acomodación»',
 [Q('J3-01','gr',G('J3-01'),'Pero su Hijo, el único que se dice propiamente Hijo, el Verbo que antes de las obras estaba con él y era engendrado, cuando al principio por medio de él creó y ordenó todas las cosas, se llama Cristo […]','2 Apol. 6 (Otto 1842, p. 296)',OTTO1),
  Q('J3-03','gr',G('J3-03'),'Al Padre de todo, que es ingénito, no se le da nombre; pues con cualquier nombre que se le llame, tiene como anterior a quien le pone el nombre. Y «Padre», «Dios», «creador», «Señor» y «dueño» no son nombres sino apelaciones tomadas de sus beneficios y obras.','2 Apol. 6 (Otto 1842, p. 296)',OTTO1),
  Q('J3-12','gr',G('J3-12'),'Todo lo que se ha dicho bien entre todos es de nosotros los cristianos: pues al Verbo que procede del Dios ingénito e inefable lo adoramos y amamos después de Dios, porque también por nosotros se hizo hombre, para hacerse partícipe de nuestros sufrimientos y procurarnos curación.','2 Apol. 13.4 (Otto 1842, p. 312)',OTTO1)],
 '<b>Por qué es difícil.</b> «Era engendrado, cuando al principio por medio de él creó…» (<i>kaì synòn kaì gennómenos, hóte tèn archèn…</i>): <b>presente</b>, ligado a la creación. Newman (<i>Arians</i>, Apéndice, p. 417) concluye: «no puede haber duda de cuál es el sentido literal… y que en consecuencia requieren alguna acomodación para conciliarlas con la enseñanza católica». <b>Resolución.</b> (1) Los dos participios van <b>juntos</b>: «estaba con él» (<i>synón</i>) <b>y</b> «era engendrado» (<i>gennómenos</i>), «antes de las obras»: el Verbo ya está con el Padre antes de crear; Otto anota que <i>gennâsthai</i> es el verbo habitual de Justino para el Verbo «que estaba con Dios» y remite a Dial. 62 («estaba junto al Padre antes de todas las criaturas»); su propia lectura del Verbo como «atributo divino» es discutible. (2) El presente «era engendrado» (participio) expresa la <b>relación permanente</b> de origen (el Padre es origen del Verbo), no un punto del tiempo: Atanasio (Or. 1.14) lo dirá así: «engendrado eterno» (ver JM16; esta lectura del participio es mía). (3) «Después de Dios adoramos al Verbo» (13.4) es adoración del Verbo hecho hombre. <b>Límite.</b> Newman tiene razón en el sentido literal: Justino no escribió «generación eterna». Aquí la lectura nicena es relectura.')

add('JM08', 'Diálogo 11, 34-38, 48, 54, 63: «Dios y Señor», «adorado», y la frase condicional sobre la preexistencia', 'Lo que Justino afirma y lo que no pretende probar a Trifón',
 [Q('J4-04','gr',G('J4-04'),'Pues Cristo ha sido proclamado rey, sacerdote, Dios, Señor, ángel, hombre, jefe, piedra y niño nacido, y primero pasible, luego subiendo al cielo, y viniendo de nuevo con gloria, y teniendo un reino eterno, como demuestro por todas las Escrituras.','Diálogo 34.2 (Trollope 1846, p. 71)',TROL),
  Q('J4-05','gr',G('J4-05'),'[…] para demostrar que Cristo es llamado Dios y Señor de los ejércitos, y Jacob, en parábola, por el Espíritu Santo […]','Diálogo 36.2 (Trollope 1846, p. 76)',TROL),
  Q('J4-13','gr',G('J4-13','οὐκ ἀπόλλυται','ἄνθρωπος διὰ τῆς παρθένου.'),'[…] no se pierde que éste es el Cristo de Dios, si no puedo demostrar que preexistía como Hijo del Hacedor del universo, siendo Dios, y que nació hombre de la virgen.','Diálogo 48.2 (Trollope 1846, p. 97)',TROL),
  Q('J7-01','gr',G('J7-01'),'[…] Que, pues, es digno de adoración, y Dios, y Cristo, atestiguado por el que hizo esto […]','Diálogo 63 (Otto 1843 vol. 2, p. 212)',OTTO2)],
 '<b>Qué dice.</b> «Dios» y «Señor de los ejércitos» (36), «Dios, Señor… ángel, hombre» (34), «digno de adoración y Dios y Cristo» (63). <b>Dos cautelas honestas.</b> (1) En 48.2 la frase es <b>condicional</b> (<i>eàn apodeîxai mè dýnômai</i>, «si no pudiera demostrar»): Justino sostiene que Cristo es el Mesías aun si no se probara su preexistencia; pero en los capítulos 56-62 y 128-129 sí intenta demostrarla. No es una renuncia a la preexistencia, es una concesión argumentativa a Trifón. (2) Los títulos «Dios» y «Señor» vienen <b>de textos bíblicos citados</b> (Sal 24, 45, 110), no de una definición propia. <b>Límite.</b> J4 (cap. 1-55) no halló en esos capítulos <i>primogénito</i>, <i>homoousios</i> ni «segundo Dios» en boca de Justino: el «otro Dios» aparece en boca de Trifón (50, 55). Los pasajes duros están más adelante (JM09-JM12).')

add('JM09', 'Pasaje difícil B (Diálogo 56): «hay otro Dios y Señor sujeto al Hacedor del universo… en número, no en voluntad»', 'El texto más difícil para la ortodoxia nicena', 
 [Q('J5-01','gr',G('J5-01'),'[…] hay, y se dice que hay, otro Dios y Señor, subordinado al Hacedor del universo, el cual se llama también Ángel por anunciar a los hombres lo que el Hacedor del universo —sobre quien no hay otro Dios— quiere anunciarles.','Diálogo 56 (Migne PG 6; ANF vol. 1, p. 223)',MIGNE),
  Q('J5-02','gr',G('J5-02'),'[…] que éste que se dice y está escrito que se apareció a Abrahán, a Jacob y a Moisés, y que es Dios, es distinto del Dios que lo hizo todo: distinto en número, digo, pero no en voluntad.','Diálogo 56 (Migne PG 6; ANF vol. 1, p. 223; ver captura JM21)',MIGNE)],
 '<b>Por qué es difícil.</b> «Otro Dios… subordinado» (<i>héteros… hypò tòn poiētḗn</i>) y «distinto en número» son las fórmulas que más usan unitarios y arrianos; y Justino mismo dice en 11.1 que «no habrá otro Dios… fuera del que hizo todo este universo» y que ni siquiera hay «otro nuestro y otro vuestro».<br><b>Resolución, en cuatro pasos.</b> (1) <b>Cada cláusula se corrige a sí misma</b>: «distinto en número, <b>pero no en voluntad</b> (<i>gnómē</i>)», y el que es «otro Dios» es el que el mismo texto llama «Dios, Ángel, Señor» y que sólo hace lo que el Hacedor quiere. No son dos principios. (2) <i>Hypó</i>, «bajo», es la relación del enviado al que envía (como en 1 Apol. 63): subordinación de <b>origen y misión</b>, no de naturaleza. (3) Bull lee «numéricamente otro» como distinción de <b>persona</b> dentro de una sola naturaleza (<i>Defensio</i> II.4.3, p. 137); es su glosa, no el vocabulario de Justino. Aquino dirá que <i>alius</i> en masculino significa sólo distinción de <i>suppositum</i> (ST I q.31 a.2); Hilario: «no dos Dioses, sino uno de uno» (De Trin. II.11). (4) Kono (1933) lee aquí un «segundo Dios» personal realmente distinto (J9-19).<br><b>Límite.</b> Este pasaje <b>no se resuelve por sí solo</b>: la ortodoxia posterior es una explicación de lo que Justino quería decir, no lo que escribió. El Dios «que hizo el mundo» sigue siendo el único «sobre quien no hay otro Dios».')

add('JM10', 'Pasaje difícil C (Diálogo 58, 126-127): «ángel», «ministro» del Padre y el Dios «ineffable»', 'Las teofanías y la acusación de que el Hijo es un ángel creado',
 [Q('J5-07','gr',G('J5-07'),'«Por Moisés, hermanos, está escrito de nuevo», decía yo, «que éste que se apareció a los patriarcas, y se dice que es Dios, es llamado también Ángel y Señor, para que también por esto lo reconozcáis ministro del Padre del universo, como ya habéis convenido, y persuadidos por más pruebas permanezcáis firmes».','Diálogo 58 (Migne PG 6; ANF p. 225)',MIGNE),
  Q('J5-16','gr',G('J5-16'),'[…] sino a aquél que según su voluntad es su Hijo, siendo Dios, y ángel por ministrar a su designio; el cual quiso también nacer hombre de la Virgen.','Diálogo 127 (Migne PG 6; ANF p. 263)',MIGNE),
  Q('J5-13','gr',G('J5-13'),'Pues si hubierais entendido lo dicho por los profetas, no negaríais que es Dios, Hijo del único, ingénito e inefable Dios.','Diálogo 126 (Migne PG 6; ANF p. 262)',MIGNE),
  Q('J7-17','gr',G('J7-17'),'[…] y el ángel de Dios, es decir, el poder de Dios que nos fue enviado por Jesucristo, lo reprende.','Diálogo 116 (Otto 1843 vol. 2, p. 388)',OTTO2)],
 '<b>Por qué es difícil.</b> El Hijo es «ángel» y «ministro» (<i>hypēretoûnta</i>); «ángel» y «poder» se identifican (116). Newman (p. 94 y 96): cuando Justino habla del Hijo como «ministro de Dios» se refiere a esos pasajes del AT donde una presencia angélica lleva los títulos y atributos divinos. <b>Resolución.</b> (1) En 126 el Hijo es «Dios, Hijo del único, ingénito e inefable Dios»: no es un ángel creado; en 127 el Padre es «inefable», no se mueve ni está en lugar alguno, por lo que las apariciones son <b>del Hijo</b> y no del Padre: es la lógica de las teofanías, no una inferioridad de naturaleza. (2) «Ángel» designa la <b>función</b> de mensajero: «se le llama ángel porque anuncia…» (56) y 1 Apol. 63.5 («lo que hay que conocer»). (3) «Según su voluntad… ministrando a su designio» es la <b>misión</b> del Hijo hacia fuera: Agustín (<i>De Trin.</i> II.13.23): al Señor Jesucristo se le llama en el profeta «Ángel del Gran Consejo», «siendo tanto el Espíritu Santo como el Hijo de Dios Dios y Señor de los ángeles». Aquino (ST I q.43 a.7 ad 5) distingue ser enviado «como ángel» de ser enviado «visiblemente» (misión visible). <b>Límite.</b> Estas dos respuestas son relectura; Newman concede que «ministro» y los títulos angélicos son vocabulario de subordinación.')

add('JM11', 'Pasaje difícil D (Diálogo 61): «Dios engendró, antes que todas las criaturas, un principio, un poder racional salido de sí mismo»', 'Con la página real de Trollope (capturas JM20)',
 [Q('J6-01','gr',G('J6-01'),'Os aduciré aún otro testimonio de las Escrituras, amigos: que Dios engendró, como principio antes de todas las criaturas, un cierto poder racional de sí mismo, al que el Espíritu Santo llama unas veces gloria del Señor, otras Hijo, otras Sabiduría, otras Ángel, otras Dios, otras Señor y Verbo, y otras se llama a sí mismo caudillo, cuando se apareció en forma humana a Josué hijo de Nun.','Diálogo 61.1 (Trollope 1846, pp. 123-124)',TROL+' (vi la página 124)'),
  Q('J6-12','gr',G('J6-12'),'Pero esta descendencia verdaderamente proferida del Padre existía junto al Padre antes que todas las criaturas, y a ésta el Padre habla, como el Verbo mostró por Salomón: que, como principio antes que todas las obras, Dios la había engendrado: la que por Salomón se llama Sabiduría.','Diálogo 62.4 (Trollope 1846, p. 127)',TROL),
  Q('J6-05','gr',G('J6-05'),'Y me dará testimonio el Verbo de la Sabiduría, éste mismo, Dios engendrado del Padre de todo, que es Verbo, y poder, y gloria del que lo engendró.','Diálogo 61 (Trollope 1846, p. 125)',TROL)],
 '<b>Por qué es difícil.</b> «Dios <b>engendró</b>… <b>antes</b> de todas las criaturas, un <b>principio</b>, un <b>poder</b> racional» (<i>archēn… dýnamin</i>) y la identificación con la Sabiduría de Prov 8:22 («el Señor me creó…», <i>éktise</i>) son las frases que arrianos y unitarios más han citado. <b>Resolución.</b> (1) El «poder» es <b>«racional» (<i>logikḗ</i>) y «de sí mismo» (<i>ex heautoû</i>)</b>: procede de Dios, no de la nada; y la misma frase le llama Hijo, Dios, Señor y Verbo. (2) 62.4: «existía <b>junto al Padre antes de todas las criaturas</b>, y a ésta el Padre habla»: es anterior a toda criatura (con lo cual no es criatura) y distinto de Dios (con quien habla). (3) 61.5: es «<b>este mismo Dios</b> engendrado del Padre de todo, que es Verbo, poder y gloria del que lo engendró»: la generación tiene por término a <b>Dios</b>. (4) Atanasio (Or. 1.14): «si se le llama engendrado eterno del Padre, con razón se le llama así»; y la frase de Prov 8 la lee la tradición posterior como <b>Sabiduría del Padre</b>. <b>Límite.</b> «Antes de todas las criaturas» no es «desde la eternidad» y «poder/principio» son términos que Justino no precisa; Kono la lee como influencia platónica, no como doctrina trinitaria cerrada.')

add('JM12', 'Pasaje difícil E (Diálogo 61, 128): «por su poder y voluntad, pero no por abscisión»', 'La respuesta de Justino a la objeción de la división; la luz del sol no es de Justino',
 [Q('J6-02','gr',G('J6-02'),'¿Y no es algo así lo que vemos también en nosotros? Pues al proferir una palabra, engendramos una palabra, no por abscisión, de modo que disminuya la palabra que está en nosotros al proferirla.','Diálogo 61.1 (Trollope 1846, p. 124; captura JM20)',TROL),
  Q('J6-03','gr',G('J6-03'),'Y vemos algo semejante en el fuego, que otro se produce sin que disminuya aquél del que se encendió la llama, sino que permanece el mismo, y lo encendido de él aparece también existiendo por sí mismo, sin disminuir aquello de lo que fue encendido.','Diálogo 61.1 (Trollope 1846, p. 124)',TROL),
  Q('J6-13','gr',G('J6-13'),'En lo ya dicho examiné brevemente el asunto: dije que este poder fue engendrado del Padre por su poder y voluntad, pero no por abscisión, como si se dividiera la esencia del Padre, como todas las demás cosas divididas y cortadas no son las mismas después que antes de ser cortadas.','Diálogo 128 (cita en Otto, Corpus apologetarum vol. 3, p. 24)','Griego: Otto 3.ª ed., citado en su aparato; leído en el PDF por un investigador')],
 '<b>Qué dice.</b> Justino mismo plantea la objeción: ¿el Padre se divide? Responde con dos analogías (la palabra y el fuego) que dicen que el engendrado «aparece existiendo por sí mismo» sin disminuir al engendrador, y rechaza explícitamente la <b>abscisión</b> (<i>apotomḗ</i>): «no como si se dividiera la esencia (<i>ousía</i>) del Padre». <b>Ojo.</b> La imagen de la luz del sol que sale y se retira es de <b>los adversarios</b> (128), que Justino <b>rechaza</b> (J6-14): no la atribuyas a Justino. <b>Resolución.</b> (1) «Esencia» y «no abscisión» son ya el vocabulario de Nicea; Bull (<i>Defensio</i> II.4.4-5, pp. 139-141) afirma que la respuesta de Justino a la «sofística de la división» es la misma que dieron los doctores católicos a los arrianos. (2) Atanasio: «por naturaleza engendra el Padre, como por naturaleza es bueno» (Or. 3.66); Hilario, Agustín y Aquino dan la distinción de <b>«por voluntad» como principio frente a como concomitancia</b> (ver JM16). <b>Límite.</b> «Por su poder y voluntad» sigue siendo «voluntad» como causa; es el punto que la tradición posterior corrige (no «por voluntad» como creatura, sino «voluntariamente y libremente», Atanasio, De Syn. 26.7).')

add('JM13', 'Pasaje difícil F (Diálogo 84, 100, 125): «primogénito de toda la creación»', '¿Primera criatura o primogénito antes de toda criatura?',
 [Q('J7-11','gr',G('J7-11'),'[…] que lo conocemos como primogénito de Dios y antes de todas las criaturas, e hijo de los patriarcas, pues por la virgen de su estirpe se hizo carne y hombre sin aspecto, sin honra y pasible […]','Diálogo 100 (Otto 1843 vol. 2, p. 340)',OTTO2),
  Q('J7-08','gr',G('J7-08'),'[…] que el primogénito de todas las criaturas se hiciera carne por vientre virginal y fuera verdaderamente niño; lo anunció de antemano por el Espíritu profético de varias maneras, para que, cuando ocurriera, se conociera como obrado por el poder y voluntad del Hacedor del universo.','Diálogo 84 (Otto 1843 vol. 2, p. 286)',OTTO2),
  Q('J7-12','gr',G('J7-12'),'Pues era unigénito del Padre del universo, engendrado de modo propio como Verbo y poder de él, y luego hombre por la virgen […]','Diálogo 105 (Otto 1843 vol. 2, p. 356)',OTTO2)],
 '<b>Por qué es difícil.</b> «Primogénito de todas las criaturas» (Col 1:15) se lee en clave arriana como «la primera criatura». <b>Resolución.</b> (1) En 100: «primogénito de Dios <b>y antes de todas las criaturas</b>» — «antes de» las criaturas no es «una de ellas». (2) En 105 es «<b>unigénito</b> (<i>monogenḗs</i>) del Padre… engendrado <b>de modo propio</b> (<i>idíōs</i>)», como Verbo y poder: un título que no se aplica a nadie más. (3) La frase de Col 1:15 la lee Novatian (<i>De Trin.</i> 21): Cristo es «primogénito de toda criatura» porque, según la divinidad, el Verbo procede del Padre <b>antes de toda criatura</b> (J10-30, inglés). <b>Límite.</b> La misma frase («antes de todas las criaturas») es la que Newman considera de sentido literal temporal; no es posible borrar esa lectura.')

add('JM14', 'Lo que dicen los estudiosos (1): defensa de la ortodoxia de Justino', 'Bull y su respuesta a la acusación de arrianismo',
 [Q('J9-01','en',EN('J9-01'),'Justino Mártir debe colocarse en la clase inmediata a los escritores apostólicos, si no enumerarse con ellos; y casi todas sus obras están llenas de tantos y tan claros testimonios de la consustancialidad del Hijo, que no puedo sino indignarme al leer las calumnias con las que ciertos escritores presuntuosos de hoy han intentado manchar la memoria de ese santísimo padre y mártir, como si coincidiera en opinión con los impíos arrianos.','Bull, Defensio fidei Nicaenae, II.4.1 (Oxford 1851, pp. 135-136)','Inglés: traducción de 1851 de Bull'),
  Q('J9-04','en',EN('J9-04'),'En estas palabras Justino enseña expresamente que el Hijo es en verdad «numéricamente otra cosa», otro, es decir, que el Padre en número, o (dicho de otro modo) en persona, pero de ningún modo distinto de Él en naturaleza; pues fue engendrado de la misma esencia de Dios Padre, y por tanto es su Hijo, consustancial con Él.','Bull, Defensio, II.4.3 (p. 137)','Inglés: traducción de 1851 de Bull'),
  Q('J9-07','en',EN('J9-07'),'No hubo católicos que afirmaran que la esencia divina se divide; es más, Justino rechaza esa noción por blasfema; ni los herejes contra los que argumenta la afirmaban, sino que, al contrario, sostenían que la naturaleza de Dios es unipersonal, precisamente para escapar de esa partición de la esencia divina.','Bull, Defensio, II.4.4 (p. 139)','Inglés: traducción de 1851 de Bull')],
 '<b>Qué muestra.</b> Bull (1685) defiende que Justino enseña la consustancialidad y que su «numéricamente otro» es distinción de persona; que Justino rechaza la división de la esencia, y que su argumento es contra los que sólo admitían «una persona». <b>Cautelas.</b> (1) Bull es un <b>abogado nicenista</b> del siglo XVII, no un testigo neutral; «en persona» y «en naturaleza» son <b>glosas suyas</b>, no vocabulario de Justino. (2) En su misma obra, Bull rechaza que Justino diga «hubo un tiempo en que no existía» atribuyéndolo a escritos espurios (JM01). (3) No pude leer el latín de Bull; cito la traducción inglesa de 1851.')

add('JM15', 'Lo que dicen los estudiosos (2): las objeciones serias', 'Newman, Kono y la acusación de «economía»',
 [Q('J9-18','en',EN('J9-18'),'Por ejemplo: Justino dice «fue engendrado cuando Dios al principio creó y ordenó todas las cosas por medio de Él» (Ap. ii. 6). […] No puede haber duda de cuál es el sentido literal de palabras como éstas, y de que en consecuencia requieren alguna acomodación para conciliarlas con la doctrina católica recibida de Deo y de SS. Trinitate.','Newman, The Arians of the Fourth Century, Apéndice, p. 417','Inglés: Newman (Longmans, 7.ª ed. 1890)'),
  Q('J9-11','en',EN('J9-11'),'Otra vez: el último Padre mencionado nos da un ejemplo de renuncia económica a una doctrina sagrada. Cuando Justino Mártir, en su discusión con el judío Trifón (150 d. C.), se encuentra incapaz de convencerle de la divinidad de Cristo desde el Antiguo Testamento, recurre a la doctrina de su Misión divina, como punto indiscutible por un lado y que ofrece, por otro, base suficiente para avanzar, cuando convenga, a la prueba de la plena verdad evangélica.','Newman, Arians, I.3, pp. 68-69','Inglés: Newman (Longmans, 7.ª ed. 1890)'),
  Q('J9-19','en',EN('J9-19'),'Tanto Filón como Justino Mártir siguieron el concepto platónico de la existencia de segundos dioses, pero en Justino el verdaderamente llamado segundo Dios se limita a Cristo, el Logos, solamente, y el Logos está personificado en plena medida.','Kono, The Logos Doctrine of Justin Martyr (1933)','Inglés: tesis de 1933 (no una monografía)')],
 '<b>Qué muestra.</b> Newman, que no es hostil a Nicea, concede que (a) el sentido <b>literal</b> de 2 Apol. 6 es temporal; (b) Justino recurre a la «misión» cuando no puede probar la divinidad desde el AT («economía»); Kono (1933) ve en Justino un «segundo Dios» personal de influencia platónica. <b>Lectura honesta.</b> El caso de Justino es parecido al de Teófilo y Tertuliano: <b>distinción real, divinidad afirmada, subordinación de origen y misión</b>; pero la formulación es preniceña y las objeciones de Newman y Kono son <b>reales</b>. Aquí no defiendo que Justino sea un nicenista; defiendo que no es arriano y que sus frases más duras se explican (no se anulan) con la distinción entre generación y misión. <b>Límite.</b> No pude abrir Barnard, Prestige, Kelly ni Bethune-Baker (restringidos en archive.org); Semisch (1840) es alemán en gótico y el OCR no sirve.')

add('JM16', 'Cómo lo resuelve la teología posterior (1): por naturaleza, no por voluntad; y sin división', 'Atanasio, Hilario, Agustín, Gregorio de Nacianzo, Aquino',
 [Q('J10-03','en',EN('J10-03'),'Un hombre construye una casa por consejo, pero engendra un hijo por naturaleza; y lo que está en la construcción empezó a existir por voluntad, y es externo al constructor; pero el hijo es propia descendencia de la esencia del padre, y no es externo a él.','Atanasio, Contra los arrianos III.62','Inglés: Newman y Robertson, NPNF 2.ª serie vol. 4'),
  Q('J10-09','en',EN('J10-09', None, 'freely;'),'Y a la vez, a los que irreverentemente dicen que el Hijo ha sido engendrado sin elección ni voluntad, rodeando así a Dios con una necesidad que excluye elección y propósito, de modo que habría engendrado al Hijo contra su voluntad, los tenemos por muy impíos y ajenos a la Iglesia […] Pues nosotros, sabiendo que Dios es absoluto y soberano sobre sí mismo, tenemos el juicio religioso de que engendró al Hijo voluntaria y libremente […]','Atanasio, De Synodis 26.7 (credo reproducido)','Inglés: Newman y Robertson, NPNF 2.ª serie vol. 4'),
  Q('J10-21','en',EN('J10-21'),'En el otro sentido, el ablativo indica la relación de principio, como se dice que el obrero obra por su voluntad, en cuanto la voluntad es el principio de su obra; y en ese sentido hay que decir que Dios Padre engendró al Hijo no por su voluntad; pero que produjo la criatura por su voluntad.','Aquino, ST I q.41 a.2','Inglés: Dominicos ingleses (newadvent)'),
  Q('J10-34','en',EN('J10-34'),'Nunca hubo un tiempo en que no fuera. Y lo mismo vale del Hijo y del Espíritu Santo. Pregúntame de nuevo y de nuevo te responderé: ¿Cuándo fue engendrado el Hijo? Cuando el Padre no fue engendrado.','Gregorio de Nacianzo, Or. 29.3','Inglés: Browne y Swallow, NPNF 2.ª serie vol. 7')],
 '<b>Aplicación a Justino (mía).</b> «Por su poder y voluntad» (Dial. 61, 128; 2 Apol. 6) se leería en clave arriana si «voluntad» fuera <b>principio</b> de la generación (como lo es de las obras). La respuesta nicena es doble: (1) <b>Por naturaleza</b>: «como el Padre es siempre bueno por naturaleza, es siempre engendrador por naturaleza» (Atanasio, Or. 3.66); Aquino: el Padre engendró al Hijo «no por su voluntad» <i>como principio</i> (a diferencia de la criatura), aunque sí con voluntad concomitante («voluntariamente y libremente», De Syn. 26.7). (2) <b>Sin tiempo</b>: «¿cuándo fue engendrado el Hijo? Cuando el Padre no fue engendrado» (Gregorio). Agustín (<i>De Trin.</i> XV.20.38) añade: prefiere «consejo de consejo y voluntad de voluntad, como sustancia de sustancia», para no hacer accidental la voluntad de Dios. <b>Honestidad.</b> Ninguna de estas fuentes cita a Justino. Aquino (q.41 a.2) cita una anatema de «De Synod.» que no está en Atanasio (queda sin resolver). Todos los textos son ingleses (newadvent); no leí el griego ni el latín.')

add('JM17', 'Cómo lo resuelve la teología posterior (2): «otro Dios»', 'Hilario, Aquino, y el planteamiento de la objeción en Tertuliano y Novaciano',
 [Q('J10-12','en',EN('J10-12'),'No son dos Dioses, sino Uno de Uno; no son dos Ingénitos, pues el Hijo nace del No-nacido.','Hilario, De Trinitate II.11','Inglés: Watson y Pullan, NPNF 2.ª serie vol. 9'),
  Q('J10-23','en',EN('J10-23'),'Esta palabra «otro» (alius), sin embargo, en el sentido masculino, significa sólo una distinción de «supuesto»; y por eso podemos decir con propiedad que «el Hijo es otro que el Padre», porque Él es otro «supuesto» de la naturaleza divina, como es otra persona y otra hipóstasis.','Aquino, ST I q.31 a.2','Inglés: Dominicos ingleses (newadvent)'),
  Q('J10-29','en',EN('J10-29'),'Pues bien, replicas: si era Dios el que habló, y también era Dios el que creó, a este paso un Dios habló y otro creó; (y así) se declaran dos Dioses.','Tertuliano, Adv. Praxean 13 (la objeción)','Inglés: Holmes, ANF vol. 3'),
  Q('J10-28','en',EN('J10-28'),'[…] siendo el segundo desde el Padre, y con el Espíritu el tercero, y declarando y manifestando Él mismo al Padre más plenamente […] el título del que es Dios y Señor fue al punto restituido a la Unidad (de la naturaleza divina)','Tertuliano, Adv. Praxean 13','Inglés: Holmes, ANF vol. 3')],
 '<b>Aplicación a Justino (mía).</b> Justino dice «otro» (<i>héteros</i>) y «en número» para negar a los que identificaban Padre e Hijo (1 Apol. 63.14: «los que dicen que el Hijo es el Padre» no conocen al Padre). Aquino precisa que «otro» en masculino es distinción de <i>suppositum</i>, no de naturaleza; Hilario: «no dos Dioses sino uno de uno». Tertuliano plantea la misma objeción («dos Dioses», <i>Adv. Prax.</i> 13) y responde que «el título de Dios y Señor se restituye a la Unidad». <b>Límite.</b> Justino mismo no tiene la distinción persona/naturaleza: su «<i>héteros theós</i> subordinado» es lo que las fórmulas posteriores explican; no es lo que él dijo. Estas fuentes no comentan a Justino.')

add('JM18', 'Recepción: qué pasó con Justino después', 'Tatiano, escritos espurios y negativos de búsqueda',
 [Q('J11-07','en',EN('J11-07'),'A todos estos herejes se añade un tal Taciano, hereje hermano. Éste fue discípulo de Justino Mártir. Después de la muerte de Justino comenzó a abrigar opiniones diferentes de las suyas.','Pseudo-Tertuliano, Adv. omnes haereses 7 (ANF vol. 3, p. 654)','Inglés: Thelwall, ANF vol. 3 (apéndice; la obra se considera pseudo-Tertuliana)'),
  Q('J11-21','en',EN('J11-21'),'La opinión que he estado describiendo es, en cuanto a las palabras, sostenida definitivamente por Justino, Taciano, Teófilo, Metodio, en Oriente; por Hipólito, Tertuliano, Novaciano, Lactancio, Zenón y Victorino, en Occidente […]','Newman, Arians, Apéndice, p. 427','Inglés: Newman (1871)')],
 '<b>Hallado.</b> Eusebio (<i>HE</i> 4.18) enumera obras de Justino; Ireneo lo cita contra Marción (Adv. haer. 4.6.2; 5.26.2); Tertuliano lo nombra como «filósofo y mártir» (Adv. Val. 5); Hipólito lo llama «el Mártir» y maestro de Taciano. <b>No hallado</b> (negativos de búsqueda, no pruebas): ningún texto leído de <b>Arrio, Asterio o Eusebio de Nicomedia cita a Justino</b>; tampoco Orígenes, Atanasio, Basilio ni Gregorio de Nacianzo en los pasajes leídos. <b>Interpretación.</b> Newman dice que la «opinión» de generación antes de la creación está en Justino, Taciano, Teófilo, Metodio, Hipólito, Tertuliano, Novaciano… (p. 427): Justino es uno entre muchos, no un caso aislado. <b>Límite.</b> Fotio, Metodio, Epifanio, Facundo y Calcedonia: sólo búsqueda web sin resultado; no los uso.')

add('JM19', 'Resumen de pasajes difíciles y cómo se resuelven', 'Veredicto honesto: trinitario «en intención», no niceno formulado', [], '__TABLE__')
